package com.pocketmusic.android;
import android.app.job.*;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;
public class SmartDownloadsTest {
 private Map<String,?> retryBefore;private Context c;private TestMusicFixtures.Snapshot snapshot;private SmartDownloads.Fetcher fetcher;private java.util.function.Predicate<Context> eligible;private Recommendations.SongSource catalogue;private List<File> generated=new ArrayList<>();
 private Track song(String id){return new Track(id,"Smart fixture "+id,"Fixture artist",120,true,"");}
 @Before public void setup()throws Exception{c=InstrumentationRegistry.getInstrumentation().getTargetContext();Assume.assumeFalse(YouTubeSession.connected(c));snapshot=new TestMusicFixtures.Snapshot(c);retryBefore=new HashMap<>(c.getSharedPreferences("smart-retry",0).getAll());c.getSharedPreferences("smart-retry",0).edit().clear().commit();fetcher=SmartDownloads.fetcher;eligible=SmartDownloads.eligible;catalogue=SmartDownloads.catalogue;c.getSystemService(JobScheduler.class).cancel(SmartDownloads.DAILY);c.getSystemService(JobScheduler.class).cancel(SmartDownloads.NOW);c.getSharedPreferences("music",0).edit().putBoolean("smartEnabled",true).putBoolean("smartConsent",true).putBoolean("smartCharging",true).putString("smartFiles","{}").remove("tasteLikes").remove("tasteHistory").remove("tasteHidden").remove("smartExcluded").commit();SmartDownloads.eligible=context->true;SmartDownloads.catalogue=(q,p)->List.of();SmartDownloads.fetcher=(context,track,stage,run)->{File file=new File(stage,track.id+".m4a");try(FileOutputStream out=new FileOutputStream(file)){out.write(new byte[2048]);}return file;};}
 @After public void cleanup()throws Exception{c.getSystemService(JobScheduler.class).cancel(SmartDownloads.DAILY);c.getSystemService(JobScheduler.class).cancel(SmartDownloads.NOW);long end=System.currentTimeMillis()+5000;while(SmartDownloads.busy()&&System.currentTimeMillis()<end)Thread.sleep(50);for(File file:SmartDownloads.files(c))file.delete();for(File f:generated)f.delete();SmartDownloads.fetcher=fetcher;SmartDownloads.eligible=eligible;SmartDownloads.catalogue=catalogue;snapshot.restore();android.content.SharedPreferences.Editor retry=c.getSharedPreferences("smart-retry",0).edit().clear();for(Map.Entry<String,?> entry:retryBefore.entrySet())retry.putLong(entry.getKey(),(Long)entry.getValue());retry.commit();}
 private void seed(List<Track> tracks)throws Exception{MusicTaste.remember(c,tracks);for(Track t:tracks)MusicTaste.played(c,t);TestMusicFixtures.seed(c,tracks);}
 @Test public void rotationAndClearNeverRemoveManualOrKeptMusic()throws Exception{
  Track a=song("smrt0000001"),b=song("smrt0000002"),manual=song("smrt0000003");File own=new File(MusicRepository.folder(c),"Manual fixture ["+manual.id+"].mp3");try(FileOutputStream out=new FileOutputStream(own)){out.write(new byte[100]);}generated.add(own);seed(List.of(a,b,manual));SmartDownloads.refresh(c,new SmartDownloads.Run());assertEquals(2,SmartDownloads.files(c).size());assertTrue(own.exists());File kept=MusicRepository.local(c,a.id);generated.add(kept);SmartDownloads.keep(c,a.id);assertFalse(SmartDownloads.owned(c,kept));c.getSharedPreferences("music",0).edit().putBoolean("smartEnabled",false).commit();SmartDownloads.clear(c);assertTrue(kept.exists());assertTrue(own.exists());assertTrue(SmartDownloads.files(c).isEmpty());
 }
 @Test public void deletingSmartSongExcludesItFromFutureRefreshes()throws Exception{Track a=song("smrt0000004");seed(List.of(a));SmartDownloads.refresh(c,new SmartDownloads.Run());File file=MusicRepository.local(c,a.id);assertNotNull(file);LocalDownloads.remove(c,file,false);assertTrue(SmartDownloads.excluded(c).contains(a.id));AtomicInteger calls=new AtomicInteger();SmartDownloads.fetcher=(context,t,stage,run)->{calls.incrementAndGet();throw new IOException("Should not download");};SmartDownloads.refresh(c,new SmartDownloads.Run());assertEquals(0,calls.get());assertNull(MusicRepository.local(c,a.id));}
 @Test public void changedFilesAreNotOwnedAndEligibilityLossCommitsNothing()throws Exception{Track a=song("smrt0000005"),b=song("smrt0000006");seed(List.of(a));SmartDownloads.refresh(c,new SmartDownloads.Run());File file=MusicRepository.local(c,a.id);generated.add(file);try(FileOutputStream out=new FileOutputStream(file,true)){out.write(1);}assertFalse(SmartDownloads.owned(c,file));seed(List.of(b));SmartDownloads.fetcher=(context,t,stage,run)->{File partial=new File(stage,"part.m4a");try(FileOutputStream out=new FileOutputStream(partial)){out.write(1);}run.stopped=true;return partial;};SmartDownloads.refresh(c,new SmartDownloads.Run());assertNull(MusicRepository.local(c,b.id));assertTrue(file.exists());}
 @Test public void stoppingScheduledJobCancelsBeforePublishingAFile()throws Exception{Track a=song("smrt0000007");seed(List.of(a));java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),cancelled=new java.util.concurrent.CountDownLatch(1);SmartDownloads.fetcher=(context,t,stage,run)->{entered.countDown();try{Thread.sleep(30000);}catch(InterruptedException e){cancelled.countDown();throw e;}throw new IOException("Fixture timeout");};SmartDownloads.schedule(c,true);try(android.os.ParcelFileDescriptor fd=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("cmd jobscheduler run -f com.pocketmusic.android "+SmartDownloads.NOW);InputStream input=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){input.readAllBytes();}assertTrue(entered.await(10,java.util.concurrent.TimeUnit.SECONDS));c.getSystemService(JobScheduler.class).cancel(SmartDownloads.NOW);assertTrue(cancelled.await(10,java.util.concurrent.TimeUnit.SECONDS));Thread.sleep(200);assertNull(MusicRepository.local(c,a.id));}
 @Test public void livePublicAacDownloadProducesPlayableOfflineAudio()throws Exception{Assume.assumeTrue("Opt-in live smart download","true".equals(InstrumentationRegistry.getArguments().getString("liveSmart")));Assume.assumeTrue("Eligible account-free emulator",SmartDownloads.deviceEligible(c));List<Track> found=MusicCatalog.songs("Kevin MacLeod Carefree","live-smart-catalogue");Track chosen=null;for(Track t:found)if(t.music&&t.durationSeconds>=30&&t.durationSeconds<=600){chosen=t;break;}assertNotNull(chosen);seed(List.of(chosen));SmartDownloads.fetcher=fetcher;SmartDownloads.refresh(c,new SmartDownloads.Run());File file=MusicRepository.local(c,chosen.id);assertNotNull("Live download failed: "+SmartDownloads.status(c),file);assertTrue(SmartDownloads.owned(c,file));android.media.MediaMetadataRetriever reader=new android.media.MediaMetadataRetriever();try{reader.setDataSource(file.getAbsolutePath());assertTrue(Long.parseLong(reader.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION))>10000);}finally{reader.release();}}
 @Test public void unavailableSongDoesNotBlockOtherCandidates()throws Exception{Track a=song("smrt0000008"),b=song("smrt0000009");seed(List.of(b,a));SmartDownloads.fetcher=(context,t,stage,run)->{if(t.id.equals(a.id))throw new IOException("Unavailable fixture");File file=new File(stage,t.id+".m4a");try(FileOutputStream output=new FileOutputStream(file)){output.write(new byte[200]);}return file;};SmartDownloads.refresh(c,new SmartDownloads.Run());assertNotNull(MusicRepository.local(c,b.id));assertNull(MusicRepository.local(c,a.id));assertTrue(SmartDownloads.status(c).contains("skipped"));}
 @Test public void cachedAccountPicksNeedNoLocalListeningHistory()throws Exception{Track a=song("smrt0000010");TestMusicFixtures.seed(c,List.of(a));assertTrue(MusicTaste.recent(c).isEmpty());assertTrue(MusicTaste.liked(c).isEmpty());SmartDownloads.refresh(c,new SmartDownloads.Run());assertNotNull(MusicRepository.local(c,a.id));}
 @Test public void incompleteFillContinuesWithoutLosingEarlierBatches()throws Exception{List<Track> tracks=new ArrayList<>();for(int i=11;i<=17;i++)tracks.add(song(String.format(java.util.Locale.ROOT,"smrt%07d",i)));TestMusicFixtures.seed(c,tracks);SmartDownloads.Run first=new SmartDownloads.Run();SmartDownloads.refresh(c,first);assertEquals(5,SmartDownloads.files(c).size());assertTrue(first.retry);SmartDownloads.Run second=new SmartDownloads.Run();SmartDownloads.refresh(c,second);assertEquals(7,SmartDownloads.files(c).size());assertFalse(second.retry);}
 @Test public void blockedAndPausedRunsRequestAutomaticRetry()throws Exception{seed(List.of(song("smrt0000018")));SmartDownloads.eligible=context->false;SmartDownloads.Run blocked=new SmartDownloads.Run();SmartDownloads.refresh(c,blocked);assertTrue(blocked.retry);SmartDownloads.eligible=context->true;SmartDownloads.Run paused=new SmartDownloads.Run();paused.stopped=true;SmartDownloads.refresh(c,paused);assertTrue(paused.retry);assertNull(MusicRepository.local(c,"smrt0000018"));}
 @Test public void foregroundWakeupSchedulesOnlyOneConstrainedFill(){c.getSharedPreferences("music",0).edit().remove("smartLastRequest").commit();SmartDownloads.requestIfDue(c);JobScheduler scheduler=c.getSystemService(JobScheduler.class);assertNotNull(scheduler.getPendingJob(SmartDownloads.NOW));scheduler.cancel(SmartDownloads.NOW);SmartDownloads.requestIfDue(c);assertNull(scheduler.getPendingJob(SmartDownloads.NOW));}
 @Test public void unavailableFirstBatchCannotStarveLaterSongs()throws Exception{List<Track> songs=new ArrayList<>();for(int i=21;i<=27;i++)songs.add(song(String.format(java.util.Locale.ROOT,"smrt%07d",i)));TestMusicFixtures.seed(c,songs);SmartDownloads.Fetcher good=SmartDownloads.fetcher;SmartDownloads.fetcher=(context,track,stage,run)->{if(Integer.parseInt(track.id.substring(4))<26)throw new IOException("Unavailable fixture");return good.fetch(context,track,stage,run);};SmartDownloads.refresh(c,new SmartDownloads.Run());assertTrue(SmartDownloads.files(c).isEmpty());assertTrue(SmartDownloads.retryAt(c,songs.get(0).id)>System.currentTimeMillis());SmartDownloads.refresh(c,new SmartDownloads.Run());assertEquals(2,SmartDownloads.files(c).size());}
 @Test public void schedulerUsesPersistedConstrainedDailyJob(){SmartDownloads.schedule(c,false);JobInfo job=c.getSystemService(JobScheduler.class).getPendingJob(SmartDownloads.DAILY);assertNotNull(job);assertTrue(job.isPersisted());assertTrue(job.isPeriodic());assertTrue(job.isRequireCharging());assertTrue(job.isRequireBatteryNotLow());assertTrue(job.isRequireStorageNotLow());assertEquals(JobInfo.NETWORK_TYPE_UNMETERED,job.getNetworkType());assertEquals(SmartDownloadJob.class.getName(),job.getService().getClassName());}
}
